  const ROLE_DESC_MAX_LEN = 200;
  const ROLE_MULTI_SELECT_ID = "field-role";
  const ROLE_DROPDOWN_PORTAL_CLASS = "employees-role-dropdown-portal";
  const DEFAULT_STORE_NAME = "上海陆家嘴店";
