    function calcTotal() {
      let total = 0;
      document.querySelectorAll('#receiverTableBody tr.receiver-primary-row input[type="number"]').forEach(function(input) {
        total += parseFloat(input.value) || 0;
      });
      document.getElementById('totalPercent').textContent = total;
      document.getElementById('totalPercent').style.color = total === 100 ? 'var(--success)' : 'var(--danger)';
    }

    function toggleWeightBtn(show) {
      var area = document.getElementById('weightBtnArea');
      if (area) area.style.display = show ? 'block' : 'none';
    }

    function updateReceiverRowWeightBtn(row) {
      var link = row ? row.querySelector('.weight-link') : null;
      if (!link) return;
      var ms = row.querySelector('.multi-select');
      var hasRole = ms && ms.querySelectorAll('input[type="checkbox"]:checked').length > 0;
      link.classList.toggle('disabled', !hasRole);
    }

    function renderReceiverRowWeights(tr) {
      var wrap = tr ? tr.querySelector('.receiver-row-weights') : null;
      if (!wrap) return;
      var raw = tr.dataset.employeeWeights;
      if (!raw) { wrap.textContent = ''; wrap.style.display = ''; return; }
      var weights;
      try { weights = JSON.parse(raw); } catch (e) { wrap.textContent = ''; return; }
      if (!weights || typeof weights !== 'object') { wrap.textContent = ''; return; }
      var parts = [];
      Object.keys(weights).forEach(function(role) {
        var empMap = weights[role];
        if (empMap && typeof empMap === 'object') {
          var empParts = [];
          Object.keys(empMap).forEach(function(emp) {
            var w = empMap[emp];
            if (w !== undefined && w !== null) empParts.push(emp + ' ' + Number(w));
          });
          if (empParts.length) parts.push(role + ': ' + empParts.join(', '));
        }
      });
      wrap.textContent = parts.length ? tipTerm('员工小费权重: ') + parts.join('；') : '';
      wrap.style.display = parts.length ? '' : 'none';
    }

    function formatWeightAsPercentage(value) {
      if (value === '' || value === null || value === undefined) return '—';
      var weight = Number(value);
      if (!Number.isFinite(weight) || weight < 0) return '—';
      var percentage = Math.round((weight * 100 + Number.EPSILON) * 100) / 100;
      return percentage.toLocaleString('en-US', {
        useGrouping: false,
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
      }) + '%';
    }

    function syncWeightPercentage(input) {
      var row = input ? input.closest('tr') : null;
      var output = row ? row.querySelector('.weight-percentage-value') : null;
      if (output) output.textContent = formatWeightAsPercentage(input.value);
    }

    function openWeightModalForRow(linkEl) {
      if (linkEl.classList.contains('disabled')) return;
      var row = linkEl.closest('tr');
      if (!row) return;
      var isTipClaim = row.classList.contains('tip-claim-row');
      var ms = row.querySelector('.multi-select');
      var roles = [];
      if (ms) ms.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb) { roles.push(cb.value); });
      var tbody = document.getElementById('weightModalBody');
      var emptyEl = document.getElementById('weightModalEmpty');
      var hintNoRole = tipTerm(isTipClaim ? '请先在计提小费接受方规则中选择接收角色' : '请先在小费接收方规则中选择角色');
      if (!tbody || roles.length === 0) {
        if (tbody) tbody.innerHTML = '';
        if (emptyEl) { emptyEl.style.display = 'block'; emptyEl.textContent = hintNoRole; }
      } else {
        var existing = {};
        try {
          if (row.dataset.employeeWeights) existing = JSON.parse(row.dataset.employeeWeights);
        } catch (e) {}
        var html = '';
        var roleEmployees = getRuleEditorRoleEmployees();
        roles.forEach(function(role) {
          var emps = roleEmployees[role] || [];
          if (emps.length === 0) return;
          emps.forEach(function(emp, i) {
            var w = (existing[role] && existing[role][emp] !== undefined) ? existing[role][emp] : 1.0;
            html += '<tr>' +
              (i === 0 ? '<td rowspan="' + emps.length + '">' + role + '</td>' : '') +
              '<td>' + emp + '</td>' +
              '<td><input type="number" value="' + w + '" step="0.1" min="0" data-native-oninput="syncWeightPercentage(this)"></td>' +
              '<td class="weight-percentage-value">' + formatWeightAsPercentage(w) + '</td></tr>';
          });
        });
        tbody.innerHTML = html;
        if (html) {
          if (emptyEl) emptyEl.style.display = 'none';
        } else {
          if (emptyEl) { emptyEl.style.display = 'block'; emptyEl.textContent = '所选角色暂无员工数据'; }
        }
      }
      var modalEl = document.getElementById('weightModal');
      if (isTipClaim) {
        modalEl.dataset.weightTipClaimId = row.dataset.claimId || '';
        modalEl.dataset.weightRowId = '';
      } else {
        modalEl.dataset.weightTipClaimId = '';
        modalEl.dataset.weightRowId = row.dataset.receiverRowId || '';
      }
      openModal('weightModal');
    }

    function saveWeight() {
      var modal = document.getElementById('weightModal');
      var tipClaimId = modal && modal.dataset.weightTipClaimId ? modal.dataset.weightTipClaimId : '';
      var tbody = document.getElementById('weightModalBody');
      var rows = tbody ? tbody.querySelectorAll('tr') : [];
      var weights = {};
      rows.forEach(function(tr) {
        var tds = tr.querySelectorAll('td');
        var roleTd = tds[0];
        var empTd = tds[1];
        var input = tr.querySelector('input[type="number"]');
        if (!roleTd || !empTd || !input) return;
        var role = roleTd.textContent.trim();
        var emp = empTd.textContent.trim();
        var val = parseFloat(input.value);
        if (isNaN(val)) val = 1;
        if (!weights[role]) weights[role] = {};
        weights[role][emp] = val;
      });
      if (tipClaimId) {
        var ttr = null;
        document.querySelectorAll('#tipClaimsTableBody tr.tip-claim-row').forEach(function(r) {
          if (r.dataset.claimId === tipClaimId) ttr = r;
        });
        if (ttr) {
          ttr.dataset.employeeWeights = JSON.stringify(weights);
          renderReceiverRowWeights(ttr);
        }
      } else {
        var rowId = modal && modal.dataset.weightRowId ? modal.dataset.weightRowId : '';
        if (rowId) {
          var tr = document.querySelector('#receiverTableBody tr[data-receiver-row-id="' + rowId + '"]')
            || document.querySelector('#orderResidualReceiverTableBody tr[data-receiver-row-id="' + rowId + '"]');
          if (tr) {
            tr.dataset.employeeWeights = JSON.stringify(weights);
            renderReceiverRowWeights(tr);
          }
        }
      }
      closeModal('weightModal');
      showNotification('员工权重保存成功');
    }

    function conditionPreviewFields(cond, pct) {
      cond = cond && typeof cond === 'object' ? cond : {};
      var fields = [];
      function add(label, value) {
        if (Array.isArray(value)) value = value.join('、');
        if (value == null || String(value).trim() === '') return;
        fields.push({ label: label, value: String(value) });
      }
      add('占比', pct == null || pct === '' ? '' : String(pct) + ' %');
      add('角色', cond.role);
      add('员工筛选角色', cond.employeeRoles);
      add('员工', cond.employee);
      add('订单区域', cond.area);
      add('订单类型', cond.orderType);
      if (cond.menu && typeof cond.menu === 'object') add('菜单', formatMenuCascadeCond(cond.menu));
      add('营业额', cond.revenueType);
      add('订单小费状态', cond.orderTipStatus === 'has_tip' ? '含小费' : (cond.orderTipStatus === 'no_tip' ? '不含小费' : ''));
      if (Array.isArray(cond.paymentMethods) && cond.paymentMethods.length) {
        add('支付方式', window.TipOutPaymentMethodApportion && TipOutPaymentMethodApportion.formatPaymentMethodsLabelZh
          ? TipOutPaymentMethodApportion.formatPaymentMethodsLabelZh(cond.paymentMethods) : cond.paymentMethods);
      }
      add(tipTerm('小费类型'), cond.tipTypes && cond.tipTypes.length ? cond.tipTypes : cond.tipType);
      if (cond.types || cond.surchargeType) add('加收类型', formatSurchargeTypeDisplay(cond.types || cond.surchargeType));
      if (cond.containsProduct && menuCascadeHasAnySelection(cond.containsProduct)) add('订单需包含商品', formatMenuCascadeCond(cond.containsProduct));
      if (cond.hours && (cond.hours.start || cond.hours.end)) add('营业时间', (cond.hours.start || '未设置') + ' - ' + (cond.hours.end || '未设置'));
      if (Array.isArray(cond.shift) && cond.shift.length) add('班次', formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) add('周期（星期）', formatWeekdaysCondDisplay(cond.weekdays));
      return fields;
    }
    function renderConditionPreview(container, cond, pct, visible) {
      if (!container) return;
      var grid = container.querySelector('.condition-preview-grid');
      if (!grid) { grid = document.createElement('dl'); grid.className = 'condition-preview-grid'; container.appendChild(grid); }
      grid.replaceChildren();
      grid.hidden = !visible;
      if (!visible) return;
      conditionPreviewFields(cond, pct).forEach(function(field) {
        var item = document.createElement('div'); item.className = 'condition-preview-item';
        var label = document.createElement('dt'); label.textContent = field.label;
        var value = document.createElement('dd'); value.textContent = field.value;
        value.title = field.value; value.tabIndex = 0;
        item.appendChild(label); item.appendChild(value); grid.appendChild(item);
      });
    }

    function formatSalesCondForDisplay(cond, omitRoleSubEmployees) {
      if (!cond || typeof cond !== 'object') return '';
      var parts = [];
      if (Array.isArray(cond.role) && cond.role.length) parts.push('角色: ' + cond.role.join(', '));
      else if (cond.role) parts.push('角色: ' + cond.role);
      if (!omitRoleSubEmployees && Array.isArray(cond.employees) && cond.employees.length) parts.push('员工: ' + cond.employees.join(', '));
      if (Array.isArray(cond.employeeRoles) && cond.employeeRoles.length) parts.push('员工筛选角色: ' + cond.employeeRoles.join(', '));
      if (Array.isArray(cond.employee) && cond.employee.length) parts.push('员工: ' + cond.employee.join(', '));
      if (cond.area) parts.push('订单区域: ' + cond.area);
      if (cond.orderType) parts.push('订单类型: ' + cond.orderType);
      if (cond.menu && typeof cond.menu === 'object') {
        var menuTxt = formatMenuCascadeCond(cond.menu);
        if (menuTxt) parts.push('菜单: ' + menuTxt);
      }
      if (cond.revenueType) parts.push('营业额: ' + cond.revenueType);
      if (cond.orderTipStatus === 'has_tip') parts.push('订单小费状态: 含小费');
      else if (cond.orderTipStatus === 'no_tip') parts.push('订单小费状态: 不含小费');
      if (Array.isArray(cond.paymentMethods) && cond.paymentMethods.length) {
        var pmLabel = (window.TipOutPaymentMethodApportion && TipOutPaymentMethodApportion.formatPaymentMethodsLabelZh)
          ? TipOutPaymentMethodApportion.formatPaymentMethodsLabelZh(cond.paymentMethods)
          : cond.paymentMethods.join('、');
        if (pmLabel) parts.push('支付方式: ' + pmLabel);
      }
      if (cond.hours && (cond.hours.start || cond.hours.end)) parts.push('营业时间: ' + (cond.hours.start || '') + '-' + (cond.hours.end || ''));
      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + formatWeekdaysCondDisplay(cond.weekdays));
      return parts.join(' | ');
    }
    function formatTipsCondForDisplay(cond) {
      if (!cond || typeof cond !== 'object') return '';
      var parts = [];
      if (Array.isArray(cond.role) && cond.role.length) parts.push('角色: ' + cond.role.join(', '));
      else if (cond.role) parts.push('角色: ' + cond.role);
      if (Array.isArray(cond.employeeRoles) && cond.employeeRoles.length) parts.push('员工筛选角色: ' + cond.employeeRoles.join(', '));
      if (Array.isArray(cond.employee) && cond.employee.length) parts.push('员工: ' + cond.employee.join(', '));
      if (cond.area) parts.push('订单区域: ' + cond.area);
      if (cond.orderType) parts.push('订单类型: ' + cond.orderType);
      if (cond.tipType) parts.push(tipTerm('小费类型: ') + cond.tipType);
      if (cond.containsProduct && menuCascadeHasAnySelection(cond.containsProduct)) {
        var cpTxt = formatMenuCascadeCond(cond.containsProduct);
        if (cpTxt) parts.push('订单需包含商品: ' + cpTxt);
      }
      if (cond.hours && (cond.hours.start || cond.hours.end)) parts.push('订单时间段: ' + (cond.hours.start || '') + '-' + (cond.hours.end || ''));
      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + formatWeekdaysCondDisplay(cond.weekdays));
      return parts.join(' | ');
    }
    function formatSurchargeCondForDisplay(cond) {
      if (!cond || typeof cond !== 'object') return '';
      if (cond.types && Array.isArray(cond.types) && cond.types.length) return '加收类型: ' + formatSurchargeTypeDisplay(cond.types);
      var parts = [];
      if (Array.isArray(cond.role) && cond.role.length) parts.push('角色: ' + cond.role.join(', '));
      else if (cond.role) parts.push('角色: ' + cond.role);
      if (Array.isArray(cond.employeeRoles) && cond.employeeRoles.length) parts.push('员工筛选角色: ' + cond.employeeRoles.join(', '));
      if (Array.isArray(cond.employee) && cond.employee.length) parts.push('员工: ' + cond.employee.join(', '));
      if (cond.area) parts.push('订单区域: ' + cond.area);
      if (cond.orderType) parts.push('订单类型: ' + cond.orderType);
      if (cond.surchargeType) {
        parts.push('加收类型: ' + formatSurchargeTypeDisplay(cond.surchargeType));
      } else if (cond.tipType) parts.push(tipTerm('小费类型: ') + cond.tipType);
      if (cond.hours && (cond.hours.start || cond.hours.end)) parts.push('订单时间段: ' + (cond.hours.start || '') + '-' + (cond.hours.end || ''));
      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + formatWeekdaysCondDisplay(cond.weekdays));
      return parts.join(' | ');
    }
    function formatManualCondForDisplay(cond) {
      if (!cond || typeof cond !== 'object') return '';
      var parts = [];
      if (Array.isArray(cond.role) && cond.role.length) parts.push('角色: ' + cond.role.join(', '));
      else if (cond.role) parts.push('角色: ' + cond.role);
      if (Array.isArray(cond.employeeRoles) && cond.employeeRoles.length) parts.push('员工筛选角色: ' + cond.employeeRoles.join(', '));
      if (Array.isArray(cond.employee) && cond.employee.length) parts.push('员工: ' + cond.employee.join(', '));
      if (cond.hours && (cond.hours.start || cond.hours.end)) parts.push('订单时间段: ' + (cond.hours.start || '') + '-' + (cond.hours.end || ''));
      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + formatWeekdaysCondDisplay(cond.weekdays));
      return parts.join(' | ');
    }
    function hasValidConditions(ruleId) {
      var card = document.getElementById('rule-' + ruleId);
      var type = (card && card.dataset.ruleType) || parsePoolRuleType(ruleId);
      var cond = poolRuleConditions[ruleId];
      if (isSalesLikePoolType(type)) {
        if (!cond || typeof cond !== 'object') return false;
        // 按个人销售额：必须至少选择一个角色
        if (type === 'personal_sales') {
          return Array.isArray(cond.role) && cond.role.length > 0;
        }
        if (Array.isArray(cond.role) && cond.role.length) return true;
        if (Array.isArray(cond.employee) && cond.employee.length) return true;
        if (cond.area) return true;
        if (cond.orderType) return true;
        if (cond.revenueType) return true;
        if (cond.orderTipStatus === 'has_tip' || cond.orderTipStatus === 'no_tip') return true;
        if (Array.isArray(cond.paymentMethods) && cond.paymentMethods.length) return true;
        if (cond.menu && menuCascadeHasAnySelection(cond.menu)) return true;
        if (cond.hours && (cond.hours.start || cond.hours.end)) return true;
        if (Array.isArray(cond.shift) && cond.shift.length) return true;
        return false;
      }
      if (type === 'tips') {
        if (!cond || typeof cond !== 'object') return false;
        if (Array.isArray(cond.role) && cond.role.length) return true;
        if (Array.isArray(cond.employee) && cond.employee.length) return true;
        if (cond.area) return true;
        if (cond.orderType) return true;
        if (cond.tipType) return true;
        if (cond.containsProduct && menuCascadeHasAnySelection(cond.containsProduct)) return true;
        if (cond.hours && (cond.hours.start || cond.hours.end)) return true;
        if (Array.isArray(cond.shift) && cond.shift.length) return true;
        if (Array.isArray(cond.weekdays) && cond.weekdays.length) return true;
        return false;
      }
      if (type === 'surcharge') {
        if (!cond || typeof cond !== 'object') return false;
        if (cond.types && Array.isArray(cond.types) && cond.types.length) return true;
        if (Array.isArray(cond.role) && cond.role.length) return true;
        if (Array.isArray(cond.employee) && cond.employee.length) return true;
        if (cond.area) return true;
        if (cond.orderType) return true;
        if (cond.surchargeType && (!Array.isArray(cond.surchargeType) || cond.surchargeType.length)) return true;
        if (cond.tipType) return true;
        if (cond.hours && (cond.hours.start || cond.hours.end)) return true;
        if (Array.isArray(cond.shift) && cond.shift.length) return true;
        if (Array.isArray(cond.weekdays) && cond.weekdays.length) return true;
        return false;
      }
      if (type === 'manual') {
        // 手动上报取值条件均为可选；有卡片未选值亦可保存
        return true;
      }
      return true;
    }
    function updatePoolRuleConditionDisplay(ruleId) {
      var el = document.getElementById('rule-' + ruleId + '-conditions');
      if (!el) return;
      var cond = poolRuleConditions[ruleId];
      var card = document.getElementById('rule-' + ruleId);
      var type = (card && card.dataset.ruleType) || parsePoolRuleType(ruleId);
      var text = '';
      if (isSalesLikePoolType(type)) text = formatSalesCondForDisplay(cond || {}, true);
      else if (type === 'tips') text = formatTipsCondForDisplay(cond || {});
      else if (type === 'surcharge') text = formatSurchargeCondForDisplay(cond || {});
      else if (type === 'manual') text = formatManualCondForDisplay(cond || {});
      var textEl = el.querySelector('.cond-text');
      if (textEl) textEl.textContent = text || '未设置';
      el.classList.toggle('empty', !text);
      var rate = card && (card.querySelector('.pool-custom-pct') || card.querySelector('.pool-source-rate input[type=number]'));
      renderConditionPreview(el, cond, rate ? rate.value : '', !!cond && Object.keys(cond).length > 0);
    }

    function saveSalesCondition() {
      if (editingDeductValueBasis) {
        var cardId = editingDeductValueBasis;
        var basis = parseDeductCardBasis(cardId);
        var sc = collectSalesConditions();
        if (!hasContributorScope(sc)) {
          showNotification('角色和员工必须选择其中一项，并至少选择一个角色或员工', 'error');
          return;
        }
        if (basis === 'tip_income') {
          delete sc.revenueType;
          sc.tipTypes = collectDeductTipTypesFromSalesExtra();
          if (!sc.tipTypes.length) {
            showNotification(tipTerm('请选择小费类型（必选）'), 'error');
            return;
          }
        } else if (!sc.revenueType) {
          sc.revenueType = 'Net Sales (税前营业额)';
        }
        if ((sc.employee || []).length && (!deductEmployeeShares[cardId] || deductEmployeeShares[cardId].mode !== 'weights')) delete deductEmployeeShares[cardId];
        if ((sc.employee || []).length || !(sc.role || []).length) delete deductAllocationMethods[cardId];
        deductValueConditions[cardId] = sc;
        if (basis === 'personal_sales_pct') {
          personalSalesPctConditions = sc;
        }
        editingDeductValueBasis = null;
        currentEditingDeductBasis = null;
        var extra = document.getElementById('salesDrawerDeductExtra');
        if (extra) { extra.style.display = 'none'; extra.innerHTML = ''; }
        var titleEl = document.querySelector('#salesDrawer .drawer-header h3');
        if (titleEl) titleEl.textContent = '设置取值条件';
        updateDeductCardConditionDisplay(cardId);
        closeDrawer('salesDrawer');
        showNotification('取值条件已保存');
        return;
      }
      if (editingPersonalSalesPctConditions) {
        var scPersonal = collectSalesConditions();
        normalizeConditionsRoleEmployeeExclusive(scPersonal);
        if (!scPersonal.revenueType) scPersonal.revenueType = 'Net Sales (税前营业额)';
        personalSalesPctConditions = scPersonal;
        var pspIds = listDeductCardIds('personal_sales_pct');
        if (pspIds.length) {
          deductValueConditions[pspIds[0]] = scPersonal;
          updateDeductCardConditionDisplay(pspIds[0]);
        }
        updatePersonalSalesPctCondDisplay();
        editingPersonalSalesPctConditions = false;
        closeDrawer('salesDrawer');
        showNotification('个人销售额取值条件保存成功');
        return;
      }
      if (currentEditingRuleId) {
        var sc = collectSalesConditions();
        normalizeConditionsRoleEmployeeExclusive(sc);
        if (getPoolRuleTypeById(currentEditingRuleId) === 'personal_sales') {
          if (!Array.isArray(sc.role) || !sc.role.length) {
            showNotification('请选择角色（必选）', 'error');
            return;
          }
          if (!sc.revenueType) sc.revenueType = 'Net Sales (税前营业额)';
        }
        poolRuleConditions[currentEditingRuleId] = sc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('salesDrawer');
      showNotification('销售额取值条件保存成功');
    }
    function saveTipClaimSalesConditions() {
      if (currentTipClaimSalesConditionClaimId) {
        var tcc = collectTipClaimSalesConditions();
        normalizeConditionsRoleEmployeeExclusive(tcc);
        tipClaimConditions[currentTipClaimSalesConditionClaimId] = tcc;
        updateTipClaimRowConditionSummary(currentTipClaimSalesConditionClaimId);
      }
      currentTipClaimSalesConditionClaimId = null;
      closeDrawer('tipClaimSalesDrawer');
      showNotification('计提取值条件已保存');
    }

    function saveTipsCondition() {
      if (editingDeductTipsCardId) {
        var cardId = editingDeductTipsCardId;
        var condition = Object.assign({}, tipsDrawerRetainedConditions, collectTipsConditions());
        if (!hasContributorScope(condition)) { showNotification('角色和员工必须选择其中一项，并至少选择一个角色或员工', 'error'); return; }
        if (condition.tipType === '__saved_tip_types__') condition.tipTypes = tipsDrawerSavedTipTypes.slice();
        else condition.tipTypes = condition.tipType ? [condition.tipType] : [];
        delete condition.tipType; delete condition.revenueType;
        if ((condition.employee || []).length && (!deductEmployeeShares[cardId] || deductEmployeeShares[cardId].mode !== 'weights')) delete deductEmployeeShares[cardId];
        if ((condition.employee || []).length || !(condition.role || []).length) delete deductAllocationMethods[cardId];
        deductValueConditions[cardId] = condition;
        updateDeductCardConditionDisplay(cardId);
        closeDrawer('tipsDrawer'); showNotification('取值条件已保存'); return;
      }
      if (currentEditingRuleId) {
        var tc = collectTipsConditions();
        normalizeConditionsRoleEmployeeExclusive(tc);
        poolRuleConditions[currentEditingRuleId] = tc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('tipsDrawer');
      showNotification(tipTerm('小费取值条件保存成功'));
    }

    function saveSurchargeCondition() {
      if (currentEditingRuleId) {
        var suc = collectSurchargeConditions();
        normalizeConditionsRoleEmployeeExclusive(suc);
        poolRuleConditions[currentEditingRuleId] = suc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('surchargeDrawer');
      showNotification('加收服务费取值条件保存成功');
    }

    function saveManualCondition() {
      if (currentEditingRuleId) {
        var mc = collectManualConditions();
        normalizeConditionsRoleEmployeeExclusive(mc);
        poolRuleConditions[currentEditingRuleId] = mc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('manualDrawer');
      showNotification(tipTerm('手动上报小费取值条件保存成功'));
    }

    function collectManualConditions() {
      var cond = {};
      var container = document.getElementById('manualConditionsContainer');
      if (!container) return cond;
      container.querySelectorAll('.condition-card').forEach(function(card) {
        var id = card.id || '';
        var type = id.replace('manual-cond-', '');
        if (!type) return;
        if (type === 'role') {
          var roleMs = card.querySelector('.role-role-select');
          if (roleMs) {
            var checked = roleMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.role = Array.from(checked).map(function(c) { return c.value; });
          }
        } else if (type === 'employee') {
          var manualEcRoleMs = card.querySelector('.employee-condition-role-select');
          var manualEcStaffMs = card.querySelector('.employee-condition-staff-select');
          if (manualEcRoleMs) {
            cond.employeeRoles = Array.from(manualEcRoleMs.querySelectorAll('input[type="checkbox"]:checked')).map(function(c) { return c.value; });
          }
          if (manualEcStaffMs) {
            cond.employee = Array.from(manualEcStaffMs.querySelectorAll('input[type="checkbox"]:not(.role-employee-select-all-cb):checked')).map(function(c) { return c.value; });
          }
        } else if (type === 'hours') {
          var inputs = card.querySelectorAll('input[type="time"]');
          cond.hours = { start: inputs[0] ? inputs[0].value : '', end: inputs[1] ? inputs[1].value : '' };
        } else if (type === 'shift') {
          var shiftMs = card.querySelector('.shift-condition-select');
          if (shiftMs) {
            var shiftChecked = shiftMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.shift = Array.from(shiftChecked).map(function(c) { return c.value; });
          }
        } else if (type === 'weekday') {
          var wMs = card.querySelector('.weekday-condition-select');
          if (wMs) {
            var wChecked = wMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.weekdays = Array.from(wChecked).map(function(c) { return c.value; });
          }
        }
      });
      return cond;
    }

