      if(!cfg||cfg.mode!=='weights')return;
      if(cfg.store!==getRuleEditorStoreName())throw new Error('门店已变化，请重新设置员工权重');
      if(!hasContributorScope(deductValueConditions[cardId]||{}))throw new Error('请先设置角色或员工取值条件');
      window.TipOutFunding.validateEmployeeShares(cfg,contributorWeightRoles(cardId,members),members);
