      button.textContent=cfg&&cfg.mode==='weights'?'修改员工权重':'设置员工权重';
      label.textContent='员工权重：未设置';
      if(!cfg||cfg.mode!=='weights')return;
      if(cfg.store&&cfg.store!==getRuleEditorStoreName()){label.textContent='员工权重：门店已变化，请重新设置';return;}
      cfg.roles=contributorWeightRoles(cardId,members);cfg.store=getRuleEditorStoreName();
